from fastapi import FastAPI, Response
from prometheus_client import Counter, generate_latest

app = FastAPI()
orders_processed = Counter("orders_processed_total", "Nombre de commandes traitées")

@app.get("/health")
def health() -> dict:
    return {"status": "ok"}

@app.get("/metrics")
def metrics() -> Response:
    return Response(generate_latest(), media_type="text/plain")

@app.post("/orders")
def create_order() -> dict:
    orders_processed.inc()  # observable par l'orchestrateur et les tableaux de bord
    return {"status": "created"}

